      <?php if ($c && $c['intro']): ?><div class="intro prose"><?= $c['intro'] ?></div><?php endif ?>
      <?php if (!empty($cardlist)): ?><p class="small"><a href="#card-list">Jump to all <?= number_format(count($cardlist)) ?> cards and prices â†“</a></p><?php endif ?>
      <?php if (!empty($links) && $page === 1): ?><nav class="related" aria-label="Related pages"><span class="muted small">Related</span><?php foreach ($links as [$t, $u]): ?><a href="<?= h($u) ?>"><?= h($t) ?></a><?php endforeach ?></nav><?php endif ?>
    </div>
  </header>

  <div class="list-layout">
    <aside class="filters" id="filters" aria-label="Filters">
      <form method="get" action="<?= h($base) ?>" data-filters>
        <?php if ($search !== ''): ?><input type="hidden" name="q" value="<?= h($search) ?>"><?php endif ?>
        <?php if (isset($_GET['sort'])): ?><input type="hidden" name="sort" value="<?= h($sort) ?>"><?php endif ?>
        <div class="fgroup">
          <label class="switch"><input type="checkbox" name="stock" value="1" <?= $f['stock'] ? 'checked' : '' ?>><span>In stock only</span><span class="count mono"><?= number_format($instock) ?></span></label>
        </div>
        <?php foreach (['game', 'section', 'lang', 'set', 'rarity'] as $k): if (empty($facets[$k])) continue; $many = count($facets[$k]) > 8; ?>
        <fieldset class="fgroup">
          <legend class="eyebrow gold"><?= $labels[$k] ?></legend>
          <?php if ($many): ?><input class="fsearch" type="search" placeholder="Filter <?= strtolower($labels[$k]) ?>s" aria-label="Filter <?= strtolower($labels[$k]) ?> list" data-fsearch><?php endif ?>
          <div class="fopts<?= $many ? ' fopts-scroll' : '' ?>">
          <?php foreach ($facets[$k] as $r): $on = in_array($r['v'], (array)($f[$k] ?? []), true); ?>
            <label class="check"><input type="checkbox" name="<?= $k ?>[]" value="<?= h($r['v']) ?>" <?= $on ? 'checked' : '' ?>><span><?= h($r['v']) ?></span><span class="count mono"><?= number_format((int)$r['n']) ?></span></label>
          <?php endforeach ?>
          </div>
        </fieldset>
        <?php endforeach ?>
        <fieldset class="fgroup">
          <legend class="eyebrow gold">Price (<?= h(currency()) ?>)</legend>
          <div class="range"><input type="number" name="min" placeholder="Min" value="<?= h($f['min']) ?>" aria-label="Minimum price" min="0"><span>â€“</span><input type="number" name="max" placeholder="Max" value="<?= h($f['max']) ?>" aria-label="Maximum price" min="0"></div>
        </fieldset>
        <button class="btn btn-block" type="submit">Apply filters</button>
      </form>
    </aside>

    <section class="results" aria-label="Products">
      <div class="toolbar">
        <button type="button" class="btn btn-sm filters-toggle" data-filters-toggle aria-controls="filters" aria-expanded="false">Filters<?= $active ? ' (' . count($active) . ')' : '' ?></button>
        <span class="mono small muted"><?= number_format($total) ?> product<?= $total === 1 ? '' : 's' ?></span>
        <div class="toolbar-right">
          <label class="sel"><span class="sr">Sort by</span>
            <select data-nav aria-label="Sort by"><?php foreach (SORTS as $k => $lab): ?><option value="<?= h(listing_url($base, $params, ['sort' => $k, 'page' => null])) ?>" <?= $k === $sort ? 'selected' : '' ?>><?= h($lab) ?></option><?php endforeach ?></select>
          </label>
          <label class="sel"><span class="sr">Per page</span>
            <select data-nav aria-label="Products per page"><?php foreach ([24, 48, 96] as $n): ?><option value="<?= h(listing_url($base, $params, ['per' => $n, 'page' => null])) ?>" <?= $n === $per ? 'selected' : '' ?>><?= $n ?> per page</option><?php endforeach ?></select>
          </label>
          <div class="seg" role="group" aria-label="View">
            <a href="<?= h(listing_url($base, $params, ['view' => 'grid', 'page' => $page])) ?>" <?= $view === 'grid' ? 'aria-current="true"' : '' ?> title="Grid view">Grid</a>
            <a href="<?= h(listing_url($base, $params, ['view' => 'list', 'page' => $page])) ?>" <?= $view === 'list' ? 'aria-current="true"' : '' ?> title="List view: fastest for big orders">List</a>
          </div>
        </div>
      </div>
      <?php if ($active): ?>
      <div class="chips"><?php foreach ($active as [$t, $u]): ?><a class="chip" href="<?= h($u) ?>"><?= h($t) ?> <span aria-hidden="true">Ã—</span><span class="sr">remove filter</span></a><?php endforeach ?><a class="chip chip-clear" href="<?= h($base . ($search !== '' ? '?q=' . urlencode($search) : '')) ?>">Clear all</a></div>
      <?php endif ?>

      <?php if (!$items): ?>
        <div class="empty lattice"><p>No results for these filters.</p><a class="btn" href="<?= h($base) ?>">Clear filters</a></div>
      <?php elseif ($view === 'list'): ?>
        <div class="table-wrap"><table class="rows">
          <thead><tr><th class="sr">Image</th><th>Product</th><th>Price per unit</th><th>Stock</th><th>Quantity</th></tr></thead>
          <tbody><?php foreach ($items as $p) view__row(['p' => $p]); ?></tbody>
        </table></div>
      <?php else: ?>
        <div class="grid"><?php foreach ($items as $p) view__card(['p' => $p]); ?></div>
      <?php endif ?>

      <?php if ($pages > 1): ?>
      <nav class="pager" aria-label="Pages">
        <?php if ($page > 1): ?><a href="<?= h(listing_url($base, $params + ['view' => null], ['page' => $page - 1])) ?>" rel="prev">â† Previous</a><?php endif ?>
        <?php $from = max(1, $page - 2); $to = min($pages, $page + 2);
        if ($from > 1) echo '<a href="' . h(listing_url($base, $params, ['page' => 1])) . '">1</a>' . ($from > 2 ? '<span>â€¦</span>' : '');
        for ($i = $from; $i <= $to; $i++) echo $i === $page ? "<span aria-current=\"page\">$i</span>" : '<a href="' . h(listing_url($base, $params, ['page' => $i])) . "\">$i</a>";
        if ($to < $pages) echo ($to < $pages - 1 ? '<span>â€¦</span>' : '') . '<a href="' . h(listing_url($base, $params, ['page' => $pages])) . "\">$pages</a>"; ?>
        <?php if ($page < $pages): ?><a href="<?= h(listing_url($base, $params, ['page' => $page + 1])) ?>" rel="next">Next â†’</a><?php endif ?>
      </nav>
      <?php endif ?>
    </section>
  </div>
  <?php if (!empty($cardlist)): $setLabel = $c['title']; $multiLang = count(array_unique(array_column($cardlist, 'language'))) > 1; ?>
  <section class="section cardlist" id="card-list" aria-labelledby="cl-h">
    <div class="sec-head"><h2 class="h2" id="cl-h"><?= h($setLabel) ?>: every card and price</h2><span class="mono small muted"><?= number_format(count($cardlist)) ?> cards</span></div>
