textarea{line-height:22px}input[type=checkbox],input[type=radio]{width:18px;height:18px;min-height:0;accent-color:var(--shu)}input[type=file]{padding:6px;border-style:dashed}
.w-small{width:90px!important;display:inline-block}
.prefix{display:flex;align-items:stretch}.prefix span{display:flex;align-items:center;padding:0 10px;background:var(--bg);border:1px solid var(--line-strong);border-right:0;border-radius:6px 0 0 6px;font-family:var(--mono);font-size:13px;color:var(--muted)}.prefix input{border-radius:0 6px 6px 0}
.row3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 14px}.row6{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:0 14px}
