.tbl{width:100%;border-collapse:collapse;font-size:14px;line-height:20px}
.tbl th{text-align:left;font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);font-weight:500;padding:10px 12px;border-bottom:1px solid var(--line);background:#FBFAF8;white-space:nowrap}
.tbl td{padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:middle}.tbl tr:last-child td{border-bottom:0}.tbl tr:hover td{background:#FBFAF8}
.tbl tr.faded td{opacity:.55}.w-check{width:36px}
.thumb{width:40px;height:40px;object-fit:contain;border:1px solid var(--line);border-radius:4px;display:block;background:var(--bg)}.thumb.empty{display:block}
.status{display:inline-block;font-size:12px;line-height:18px;padding:1px 8px;border-radius:10px;font-weight:500;white-space:nowrap}
.status.green{background:var(--matcha-soft);color:var(--matcha)}.status.amber{background:var(--kin-soft);color:var(--kin)}.status.blue{background:var(--ai-soft);color:var(--ai)}.status.grey{background:var(--bg);color:var(--muted)}
.filters{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:12px}.filters input,.filters select{width:auto;flex:1 1 150px}.filters input[type=search]{flex:2 1 240px}
.bulkbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:10px 12px}.bulkbar select{width:auto}.bulkbar label{margin:0}
.pager{display:flex;gap:16px;align-items:center;justify-content:center;margin:16px 0}
.tabs{display:flex;flex-wrap:wrap;gap:4px;border-bottom:1px solid var(--line);margin-bottom:16px}.tabs a{padding:8px 14px;color:var(--muted);text-decoration:none;border-bottom:2px solid transparent;margin-bottom:-1px}.tabs a[aria-current],.tabs a:hover{color:var(--ink);border-bottom-color:var(--shu)}
.edit-grid{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:20px;align-items:start}
@media(max-width:1100px){.edit-grid{grid-template-columns:1fr}}
.sticky-save{position:sticky;bottom:0;display:flex;flex-direction:column;gap:8px;background:var(--bg);padding:12px 0 16px;z-index:5}
.photo{border:1px dashed var(--line-strong);border-radius:8px;min-height:160px;display:grid;place-items:center;margin-bottom:14px;background:var(--bg)}.photo img{max-height:260px;object-fit:contain}
.editor{border:1px solid var(--line-strong);border-radius:8px;overflow:hidden;margin-bottom:14px}
.editor .toolbar{display:flex;flex-wrap:wrap;gap:4px;padding:6px;border-bottom:1px solid var(--line);background:#FBFAF8}
.editor .toolbar button,.tb-file{height:30px;min-width:34px;padding:0 8px;border:1px solid var(--line);border-radius:4px;background:#fff;cursor:pointer;font:inherit;font-size:13px;display:inline-flex;align-items:center;margin:0;flex-direction:row;font-weight:400}
